void print_rxdataF(ru_t *ru, fp_t *fp) {
    int nb_rx = ru->nb_rx;
    int symbols = fp->symbols_per_slot;
    int ofdm_size = fp->ofdm_symbol_size;

    for (int i = 0; i < nb_rx; i++) {
        int32_t *data = ru->common.rxdataF[i];
        if (!data) {
            printf("Channel %d: rxdataF is NULL\n", i);
            continue;
        }

        printf("Channel %d:\n", i);
        for (int buffer = 0; buffer < NUMBER_RX_BUFFERS; buffer++) {
            printf("  RX Buffer %d:\n", buffer);
            for (int symbol = 0; symbol < symbols; symbol++) {
                printf("    Symbol %d: [", symbol);
                for (int ofdm = 0; ofdm < ofdm_size; ofdm++) {
