Here's an example demonstrating a blocking `read()` call being interrupted by a signal, with EINTR handling:

```c
#include <stdio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

void sig_handler(int signum) {
    printf("Received signal %d\n", signum);
}

int main() {
    struct sigaction sa;
    sigemptyset(&sa.sa_mask);
    sa.sa_handler = sig_handler;
    sa.sa_flags = 0; // Don't restart system calls

    // Set up SIGALRM handler
    if (sigaction(SIGALRM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Schedule alarm after 2 seconds
    alarm(2);

    char buffer[100];
    ssize_t bytes_read;
    do {
        bytes_read = read(STDIN_FILENO, buffer, sizeof(buffer));
    } while (bytes_read == -1 && errno == EINTR);

    if (bytes_read == -1) {
        perror("read");
        return 1;
    }

    printf("Read %zd bytes: %.*s\n", 
           bytes_read, (int)bytes_read, buffer);

    return 0;
}
```

Key aspects of this example:

1. **Signal Handling Setup**:
   - Uses `sigaction()` to properly configure the SIGALRM handler
   - `sa_flags = 0` ensures system calls aren't automatically restarted

2. **Alarm Trigger**:
   - `alarm(2)` schedules a SIGALRM to occur after 2 seconds
   - This will interrupt any blocking system call during that time

3. **Read Loop**:
   - Uses a `do...while` loop to retry the read
   - Checks specifically for `EINTR` to handle signal interruptions
   - Will retry the read if interrupted by the signal

4. **Error Handling**:
   - Detects other errors (like invalid file descriptors) with `perror()`
   - Handles normal termination (EOF) naturally through `read()` return value

5. **Signal Notification**:
   - The signal handler prints a message when the signal is received
   - Shows the signal is being properly delivered

To test this:
1. Compile and run the program
2. Let it sit without providing input for 2 seconds
3. The program will print the signal notification
4. After the signal, the read will be retried
5. Provide input (and press Enter) to see the data read

This demonstrates:
- How signals can interrupt blocking system calls
- Proper use of `EINTR` checking and retry logic
- Safe signal handler configuration
- Correct error propagation for other conditions

Note: On some systems, the actual SIGALRM number might vary (commonly 14), but the behavior remains consistent. The program will print the actual signal number received.

Here's a C++ code snippet that sets up a TCP server listening on port 888 and reads data from clients:

```cpp
#include <iostream>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <cstdlib>
#include <cstring>

// Error handling function
void error(const char *msg) {
    perror(msg);
    exit(1);
}

int main() {
    int sockfd, connfd;
    struct sockaddr_in serv_addr, cli_addr;
    socklen_t clilen = sizeof(cli_addr);

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) error("ERROR opening socket");

    // Allow socket reuse (avoid "Address already in use" errors)
    int opt = 1;
    setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    // Zero out the server struct
    memset(&serv_addr, 0, sizeof(serv_addr));

    // Configure server address
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(888); // Port 888

    // Bind the socket to the port
    if (bind(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0)
        error("ERROR on binding");

    // Start listening for connections
    listen(sockfd, 5);
    std::cout << "Server listening on port 888..." << std::endl;

    while(true) {
        // Accept incoming connection
        connfd = accept(sockfd, (struct sockaddr *)&cli_addr, &clilen);
        if (connfd < 0) error("ERROR on accept");

        std::cout << "Accepted connection from client" << std::endl;

        char buffer[256];
        bool done = false;
        while (!done) {
            // Read data from client
            ssize_t n = read(connfd, buffer, 255);
            if (n < 0) error("ERROR reading from socket");
            if (n == 0) {
                done = true; // Connection closed by client
                continue;
            }

            buffer[n] = 0; // Null-terminate the string
            std::cout << "Received: " << buffer << std::endl;
        }

        // Close client connection
        close(connfd);
    }

    // Close server socket (unreachable in loop, but included for completeness)
    close(sockfd);
    return 0;
}
```

Key points:
1. This is a TCP server (SOCK_STREAM) for reliable connections
2. Listens on port 888 (requires root privileges on Unix-like systems because it's a privileged port below 1024)
3. Reads data from clients until they close the connection
4. Handles multiple clients sequentially (one at a time)
5. Includes basic error handling and socket reuse configuration

To use this code:
1. Compile with: `g++ server.cpp -o server`
2. Run with root privileges (if using port 888): `sudo ./server`
3. To use a non-privileged port (e.g., 8088), change `htons(888)` to `htons(8088)` and run without sudo

Note: For UDP packets, you would need to use `SOCK_DGRAM` and handle packets differently without connection setup. This implementation uses TCP for connection-oriented communication.

