  inputSize: number;
  Wx: number[][]; // Input-to-hidden weights (hidden x input)
  Wh: number[][]; // Hidden-to-hidden weights (hidden x hidden)
  b: number[];    // Hidden layer bias (hidden)

  constructor(inputSize: number, hiddenSize: number) {
    this.inputSize = inputSize;
    this.hiddenSize = hiddenSize;

    // Initialize parameters with small random values
    this.Wx = this.initializeMatrix(hiddenSize, inputSize);
    this.Wh = this.initializeMatrix(hiddenSize, hiddenSize);
    this.b = this.initializeVector(hiddenSize);
  }

  // Helper functions
  private initializeMatrix(rows: number, cols: number): number[][] {
    return Array.from({ length: rows }, () =>
      Array.from({ length: cols }, () => (Math.random() * 2 - 1) * 0.1)
    );
  }

  private initializeVector(size: number): number[] {
    return Array.from({ length: size }, () => (Math.random() * 2 - 1) * 0.1);
  }

  private multiplyMatrixVector(matrix: number[][], vector: number[]): number[] {
    const rows = matrix.length;
    const cols = matrix[0].length;
    const result = new Array(rows).fill(0);

    for (let i = 0; i < rows; i++) {
      for (let j = 0; j < cols; j++) {
        result[i] += matrix[i][j] * vector[j];
      }
    }
    return result;
  }

  private addVectors(a: number[], b: number[]): number[] {
    return a.map((val, idx) => val + b[idx]);
  }

  // Forward pass through the network
  forward(inputs: number[][]): number[][] {
    const T = inputs.length;
    let h_prev = Array(this.hiddenSize).fill(0); // Initial hidden state
    const hiddenStates: number[][] = [];

    for (let t = 0; t < T; t++) {
      const x_t = inputs[t];

      // Compute input contribution
      const Wx_x = this.multiplyMatrixVector(this.Wx, x_t);

      // Compute hidden contribution
      const Wh_h = this.multiplyMatrixVector(this.Wh, h_prev);

      // Combine contributions with bias
      const sum = this.addVectors(Wx_x, Wh_h);
      const pre_activation = this.addVectors(sum, this.b);

      // Apply activation function (tanh)
      const h_t = pre_activation.map(x => Math.tanh(x));

      hiddenStates.push(h_t);
      h_prev = h_t;
    }

    return hiddenStates;
  }
}

// Example usage:
const rnn = new RNN(2, 3); // Input size 2, hidden size 3
const inputs = [[0.5, 0.3], [0.2, 0.8], [0.7, 0.1]];
const outputs = rnn.forward(inputs);

console.log("Hidden states after each time step:");
outputs.forEach((state, idx) => 
  console.log(`Time step ${idx + 1}:`, state));
```

### Key Features:
1. **Core RNN Structure**:
   - Maintains hidden state across time steps
   - Uses tanh activation function
   - Includes input-to-hidden (Wx) and hidden-to-hidden (Wh) weights

2. **Initialization**:
   - Weights and biases initialized with small random values
   - Xavier-like initialization scaling (0.1 factor)

3. **Forward Pass**:
   - Processes input sequences step-by-step
   - Returns hidden states for each time step
   - Computes:  
     `h_t = tanh(Wx * x_t + Wh * h_{t-1} + b)`

4. **Helper Functions**:
   - Matrix-vector multiplication
   - Vector addition
   - Basic dimensionality checks (implicit in multiplication)

### Usage:
1. Create an RNN instance with desired input and hidden sizes
2. Pass a sequence of input vectors to `forward()`
3. The method returns hidden states for each time step in the sequence

### Limitations:
- No output layer or prediction mechanism
- No backpropagation or training capabilities
- No learning rate or optimization
- Uses basic tanh activation (no softmax or ReLU)

This implementation demonstrates the fundamental mechanics of an RNN's hidden state processing. For practical use, you would need to add loss functions, backpropagation, and training loops.

Here's a basic implementation of a sprite editor in JavaScript using HTML5 Canvas. This editor allows you to:

1. Upload an image
2. Draw on top of the image with different colors and brush sizes
3. Select rectangular regions
4. Save the selected area or the full canvas as an image

```html
<!DOCTYPE html>
<html>
<head>
    <title>Sprite Editor</title>
    <style>
        #editorCanvas, #selectionCanvas {
            position: absolute;
            top: 0;
            left: 0;
            border: 1px solid black;
        }
        #selectionCanvas {
            pointer-events: none; /* Allow mouse events to pass through */
        }
        #controls {
            margin-top: 20px;
        }
    </style>
</head>
<body>
    <input type="file" id="imageInput" accept="image/*">
    <canvas id="editorCanvas"></canvas>
    <canvas id="selectionCanvas"></canvas>

    <div id="controls">
        <button onclick="saveSprite()">Save Sprite</button>
        <button onclick="resetCanvas()">Reset</button>
        <select id="toolSelect">
            <option value="draw">Draw</option>
            <option value="select">Select</option>
        </select>
        <input type="color" id="brushColor" value="#000">
        <input type="range" id="brushSize" min="1" max="20" value="5">
    </div>

    <script>
        const editorCanvas = document.getElementById('editorCanvas');
        const selectionCanvas = document.getElementById('selectionCanvas');
        const ctx = editorCanvas.getContext('2d');
        const selectionCtx = selectionCanvas.getContext('2d');

        let originalImage = null;
        let isDrawing = false;
        let isSelecting = false;
        let startX, startY;
        let selectionBox = null;
        let currentMode = 'draw';
        let currentColor = '#000';
        let currentLineWidth = 5;

        // Initialize controls
        document.getElementById('brushColor').addEventListener('input', (e) => {
            currentColor = e.target.value;
        });
        document.getElementById('brushSize').addEventListener('input', (e) => {
            currentLineWidth = e.target.value;
        });
        document.getElementById('toolSelect').addEventListener('change', (e) => {
            currentMode = e.target.value;
        });

        // Handle image upload
        document.getElementById('imageInput').addEventListener('change', function(e) {
            const file = e.target.files[0];
            if (file) {
                const img = new Image();
                img.src = URL.createObjectURL(file);
                img.onload = function() {
                    originalImage = img;
                    editorCanvas.width = img.width;
                    editorCanvas.height = img.height;
                    selectionCanvas.width = img.width;
                    selectionCanvas.height = img.height;

                    ctx.drawImage(img, 0, 0);
                    resetCanvas();
                };
            }
        });

        // Mouse event handlers
        editorCanvas.addEventListener('mousedown', (e) => {
            const rect = editorCanvas.getBoundingClientRect();
            startX = e.clientX - rect.left;
            startY = e.clientY - rect.top;
            isDrawing = true;

            if (currentMode === 'select') {
                isSelecting = true;
                selectionBox = { 
                    x1: startX, y1: startY,
                    x2: startX, y2: startY 
                };
            }
        });

        editorCanvas.addEventListener('mousemove', (e) => {
            if (!isDrawing) return;

            const rect = editorCanvas.getBoundingClientRect();
            const currentX = e.clientX - rect.left;
            const currentY = e.clientY - rect.top;

            if (currentMode === 'draw') {
                ctx.beginPath();
                ctx.lineJoin = 'round';
                ctx.strokeStyle = currentColor;
                ctx.lineWidth = currentLineWidth;
                ctx.moveTo(startX, startY);
                ctx.lineTo(currentX, currentY);
                ctx.closePath();
                ctx.stroke();
                startX = currentX;
                startY = currentY;
            } else if (currentMode === 'select' && isSelecting) {
                selectionBox.x2 = currentX;
                selectionBox.y2 = currentY;
                updateSelection();
            }
        });

        editorCanvas.addEventListener('mouseup', (e) => {
            isDrawing = false;
            if (currentMode === 'select') {
                isSelecting = false;
            }
        });

        // Selection helper functions
        function updateSelection() {
            selectionCtx.clearRect(0, 0, selectionCanvas.width, selectionCanvas.height);

            const x1 = Math.min(selectionBox.x1, selectionBox.x2);
            const y1 = Math.min(selectionBox.y1, selectionBox.y2);
            const x2 = Math.max(selectionBox.x1, selectionBox.x2);
            const y2 = Math.max(selectionBox.y1, selectionBox.y2);

            selectionCtx.strokeStyle = 'red';
            selectionCtx.lineWidth = 2;
            selectionCtx.setLineDash([5, 5]);
            selectionCtx.strokeRect(x1, y1, x2 - x1, y2 - y1);
        }

        // Save functionality
        function saveSprite() {
            if (!originalImage) return;

            let x, y, width, height;

            if (selectionBox) {
                const x1 = Math.min(selectionBox.x1, selectionBox.x2);
                const y1 = Math.min(selectionBox.y1, selectionBox.y2);
                const x2 = Math.max(selectionBox.x1, selectionBox.x2);
                const y2 = Math.max(selectionBox.y1, selectionBox.y2);

                x = x1;
                y = y1;
                width = x2 - x1;
                height = y2 - y1;
            } else {
                x = 0;
                y = 0;
                width = editorCanvas.width;
                height = editorCanvas.height;
            }

            const tempCanvas = document.createElement('canvas');
            tempCanvas.width = width;
            tempCanvas.height = height;
            const tempCtx = tempCanvas.getContext('2d');
            tempCtx.drawImage(editorCanvas, x, y, width, height, 0, 0, width, height);

            const link = document.createElement('a');
            link.href = tempCanvas.toDataURL();
            link.download = 'sprite.png';
            link.click();
        }

        // Reset functionality
        function resetCanvas() {
            ctx.clearRect(0, 0, editorCanvas.width, editorCanvas.height);
            ctx.drawImage(originalImage, 0, 0);

            selectionCtx.clearRect(0, 0, selectionCanvas.width, selectionCanvas.height);
            selectionBox = null;
        }
    </script>
</body>
</html>
```

This code provides a basic sprite editor with these features:

