Here's a Connect-4 game written in Python:

```python
def create_board():
    return [[' ' for _ in range(7)] for _ in range(6)]

def get_next_open_row(board, col):
    for row in reversed(range(6)):
        if board[row][col] == ' ':
            return row
    return -1

def print_board(board):
    for row in reversed(board):  # Display bottom row first
        print(" ".join(row))
    print("0 1 2 3 4 5 6")

def winning_move(board, piece):
    # Check horizontal locations for win
    for row in range(6):
        for col in range(4):
            if all(board[row][col + i] == piece for i in range(4)):
                return True

    # Check vertical locations for win
    for col in range(7):
        for row in range(3):
            if all(board[row + i][col] == piece for i in range(4)):
                return True

    # Check positively sloped diagonals
    for row in range(3):
        for col in range(4):
            if all(board[row + i][col + i] == piece for i in range(4)):
                return True

    # Check negatively sloped diagonals
    for row in range(3, 6):
        for col in range(4):
            if all(board[row - i][col + i] == piece for i in range(4)):
                return True

    return False

def is_board_full(board):
    return all(cell != ' ' for cell in board[0])

def main():
    board = create_board()
    game_over = False
    turn = 0  # 0 for Player 1 (X), 1 for Player 2 (O)

    while not game_over:
        print_board(board)
        player = "Player 1" if turn == 0 else "Player 2"
        piece = 'X' if turn == 0 else 'O'

        try:
            col = int(input(f"{player}, choose a column (0-6): "))
        except ValueError:
            print("Invalid input. Please enter a number between 0-6.")
            continue

        if not 0 <= col <= 6:
            print("Column must be between 0 and 6.")
            continue

        row = get_next_open_row(board, col)
        if row == -1:
            print("That column is full. Choose another.")
            continue

        # Place the piece
        board[row][col] = piece

        # Check for win
        if winning_move(board, piece):
            print_board(board)
            print(f"{player} wins! 🎉")
            game_over = True
        else:
            # Check for draw
            if is_board_full(board):
                print_board(board)
                print("It's a draw! 🥲")
                game_over = True

        # Switch players
        turn = (turn + 1) % 2

if __name__ == "__main__":
    main()
```

**How to play:**
1. Players take turns choosing a column (0-6) to drop their disc ('X' or 'O')
2. The disc falls to the lowest available spot in the chosen column
3. The first player to get 4 in a row (horizontal, vertical, or diagonal) wins
4. If all columns are filled without a winner, it's a draw

**Key features:**
- Clear terminal-based interface
- Input validation for column selection
- Automatic win/draw detection
- Colorless but clear visual display using 'X' and 'O'

